# (feastDate, name, tradition, description, patronOf) - Protestant / Anglican calendars, July to December.
# Dates follow the Lutheran (LCMS/ELCA) and Episcopal calendars.
P = "protestant"
PA = "protestant,anglican"
A = "anglican"

DATA = [
    ("July 1", "Catherine Winkworth and John Mason Neale", PA, "Hymn translators of the nineteenth century. Catherine Winkworth (1827-1878) rendered German chorales such as 'Now Thank We All Our God' into English; John Mason Neale (1818-1866) translated Greek and Latin hymns including 'O Come, O Come, Emmanuel'.", "Hymn translators, choirs"),
    ("July 2", "Moses the Black", A, "Ethiopian former robber (c. 330-405) who became a monk in the Egyptian desert and a teacher of gentleness. He was killed by raiders while refusing to fight.", "Reformed criminals, non-violence"),
    ("July 3", "Thomas, Apostle", P, "The apostle who doubted until he saw the risen Lord and then confessed 'my Lord and my God'. Tradition says he carried the Gospel to India.", "India, those who doubt"),
    ("July 4", "Independence Day", A, "The Episcopal Church marks the anniversary of the American Declaration of Independence with prayers for the nation and its people.", "The nation, those who pray for their country"),
    ("July 5", "Cyril and Methodius", P, "Slovak Lutheran churches remember the brothers who brought the Gospel to the Slavs and gave them a written language in the ninth century.", "The Slavs, translators"),
    ("July 6", "Jan Hus", P, "Czech priest and reformer (c. 1372-1415) who preached from the Bible in the people's language and was burned at the stake at Constance on July 6. The Moravian and other Protestant churches trace their roots to his witness.", "Czech lands, those who stand for truth"),
    ("July 8", "Priscilla and Aquila", A, "The Episcopal Church remembers the couple who hosted Paul and taught Apollos, a model of shared ministry in marriage.", "Married couples"),
    ("July 10", "John Calvin's Birthday", P, "John Calvin was born on July 10, 1509, at Noyon in France. Reformer of Geneva, his 'Institutes of the Christian Religion' shaped the Reformed churches around the world.", "Reformed churches, theologians"),
    ("July 11", "Benedict of Nursia", PA, "Italian abbot (c. 480-547) whose Rule shaped Western monasticism with its balance of prayer and work. Lutherans and Anglicans remember him on July 11.", "Monks, students, Europe"),
    ("July 12", "Nathan Soderblom", P, "Archbishop of Uppsala (1866-1931), a leader in the early ecumenical movement who convened the 1925 Stockholm conference on 'Life and Work' and won the Nobel Peace Prize in 1930.", "Church unity, peacemakers"),
    ("July 14", "Argula von Grumbach", A, "Bavarian noblewoman (c. 1492-1554) who wrote to the University of Ingolstadt in defence of a student persecuted for Lutheran views, becoming one of the first women writers of the Reformation.", "Women writers, those who speak for conscience"),
    ("July 15", "The Division of the Holy Apostles", P, "A historic feast remembering the apostles' departure from Jerusalem to carry the Gospel to the ends of the earth.", "Missionaries"),
    ("July 16", "Ruth the Moabite", P, "The woman who said to Naomi 'where you go I will go', joined Israel, and became the great-grandmother of King David and an ancestor of Jesus.", "Daughters-in-law, loyal friends, immigrants"),
    ("July 17", "Isaac Watts' Birthday and William White", PA, "Isaac Watts, the 'father of English hymnody', was born on July 17, 1674. William White (1748-1836) was the first Episcopal bishop of Pennsylvania and shaped the early Episcopal Church.", "Hymn writers, bishops"),
    ("July 19", "Macrina the Younger", A, "Sister of Basil and Gregory of Nyssa (c. 327-379), who turned her family home into a community of prayer and taught her brothers.", "Teachers, sisters in faith"),
    ("July 20", "Elijah the Prophet", P, "The prophet who confronted the prophets of Baal on Mount Carmel and heard the Lord in a 'still small voice'. He was taken up in a whirlwind and appeared with Christ at the Transfiguration.", "Prophets, those who pray in distress"),
    ("July 21", "Ezekiel the Prophet", P, "Priest and prophet in exile in Babylon, who saw visions of God's glory and the valley of dry bones coming to life, a sign of hope for the exiles.", "Exiles, those who hope for renewal"),
    ("July 22", "Mary Magdalene", PA, "The woman healed by Jesus who stayed at the cross and was the first to see the risen Lord. The Church calls her 'apostle to the apostles'.", "Those who are healed, women disciples"),
    ("July 23", "Birgitta of Sweden", P, "Swedish noblewoman and mystic (c. 1303-1373) who founded the Bridgettines, received visions and urged the Pope to return to Rome.", "Sweden, mystics, widows"),
    ("July 24", "John Newton's Birthday and Thomas a Kempis", PA, "John Newton, former slave-ship captain and author of 'Amazing Grace', was born on July 24, 1725 (Old Style; August 4 in today's calendar). Thomas a Kempis (c. 1380-1471), author of 'The Imitation of Christ', is remembered on the same date in the Episcopal calendar.", "Those redeemed from sin, devotional writers"),
    ("July 25", "James, Apostle", PA, "James the son of Zebedee, called with his brother John from their fishing boat. He was the first of the twelve to die for the faith, killed by Herod Agrippa around 44.", "Pilgrims, fishermen"),
    ("July 26", "Anne and Joachim, Parents of the Virgin Mary", A, "The traditional names of the parents of Mary, remembered by Anglicans as a sign of the blessing of grandparents.", "Grandparents"),
    ("July 27", "William Reed Huntington", A, "Episcopal priest (1838-1909) whose 'Church Idea' helped shape the Chicago-Lambeth Quadrilateral, a basis for Christian unity.", "Ecumenists, priests"),
    ("July 28", "Johann Sebastian Bach, Heinrich Schutz and George Frideric Handel", PA, "Three giants of church music. Bach (1685-1750) wrote cantatas, passions and the Mass in B minor; Schutz (1585-1672) was the father of German church music; Handel (1685-1759) wrote 'Messiah'.", "Musicians, choirs, composers"),
    ("July 29", "William Wilberforce", PA, "English evangelical politician (1759-1833) who devoted his life to ending the slave trade. He heard the news that slavery would be abolished in the British Empire three days before his death on July 29.", "Abolitionists, politicians"),
    ("July 30", "Robert Barnes", P, "English priest (c. 1495-1540) who studied at Cambridge, befriended Luther and was burned at Smithfield as a Reformation martyr.", "Martyrs, confessors"),
    ("July 31", "Joseph of Arimathea", P, "The rich member of the council who asked Pilate for the body of Jesus and buried him in his own new tomb. He is remembered for courage after hiding his faith.", "Those who give honour to the dead"),

    ("August 1", "Joseph of Arimathaea", A, "The Episcopal Church honours Joseph, the disciple who offered his tomb for the burial of Jesus.", "Undertakers, disciples"),
    ("August 3", "Joanna, Mary and Salome", PA, "Three of the women who came to the tomb on Easter morning with spices and were the first to hear the news of the resurrection.", "Women who witness to the resurrection"),
    ("August 7", "John Mason Neale", A, "Anglican priest and hymn writer (1818-1866), warden of Sackville College, who translated many ancient hymns, including 'Good King Wenceslas' words and 'All glory, laud and honour'.", "Hymn writers, translators"),
    ("August 8", "Dominic", PA, "Spanish priest (c. 1170-1221) who founded the Order of Preachers to teach the faith with preaching and study. Lutherans and Episcopalians honour him on August 8.", "Preachers, scholars"),
    ("August 9", "Edith Stein", A, "German philosopher (1891-1942), a Jewish convert to Catholicism who became a Carmelite sister and was killed at Auschwitz.", "Philosophers, converts, martyrs"),
    ("August 10", "Lawrence of Rome", PA, "Deacon of Rome who, when asked to hand over the treasure of the Church, brought the poor and said 'these are the Church's treasures'. He was martyred in 258.", "Deacons, the poor"),
    ("August 11", "Clare of Assisi", PA, "Italian abbess (1194-1253), friend of Francis, who founded the Poor Clares and lived in radical poverty at San Damiano.", "Contemplatives, those who seek simplicity"),
    ("August 12", "Florence Nightingale", A, "English nurse (1820-1910) who reformed military hospitals and founded the modern nursing profession, guided by her faith.", "Nurses"),
    ("August 13", "Florence Nightingale and Clara Maass", P, "Lutherans remember Florence Nightingale and Clara Maass (1876-1901), an American nurse who volunteered for a yellow-fever experiment and died on August 24 after serving the sick.", "Nurses, those who serve the sick"),
    ("August 14", "Maximilian Kolbe and Kaj Munk", P, "Maximilian Kolbe, a Polish Franciscan, gave his life in place of another prisoner at Auschwitz in 1941. Kaj Munk (1898-1944), a Danish Lutheran pastor and playwright, was killed by the Nazis for his preaching.", "Martyrs of conscience, prisoners"),
    ("August 15", "Mary, Mother of Our Lord", PA, "Lutherans and Anglicans honour Mary as the mother of the Lord, blessed among women, who said 'let it be to me according to your word'.", "Mothers, the Church"),
    ("August 16", "Isaac the Patriarch", P, "The son of Abraham and Sarah, child of promise, who was spared at the altar and became the father of Jacob and Esau. His life is remembered for trust.", "Those who trust in God's promises"),
    ("August 17", "William Carey's Birthday and Johann Gerhard", P, "William Carey, the 'father of modern missions', was born on August 17, 1761. Johann Gerhard (1582-1637) was a Lutheran theologian whose 'Sacred Meditations' were widely read.", "Missionaries, theologians"),
    ("August 19", "Bernard of Clairvaux", P, "French Cistercian abbot (1090-1153), preacher and hymn writer, author of 'Jesus, the Very Thought of Thee' and 'O Sacred Head, Now Wounded'. Lutherans remember him on August 19.", "Abbots, hymn writers"),
    ("August 20", "William Booth", P, "English Methodist preacher (1829-1912) who founded the Salvation Army to reach the poor of London. He died on August 20.", "The poor, those who serve the homeless"),
    ("August 24", "Bartholomew, Apostle", PA, "One of the twelve apostles, usually identified with Nathanael, in whom Jesus saw 'no deceit'. Tradition says he preached in India and Armenia.", "Apostles, Armenia"),
    ("August 25", "Louis IX of France", A, "King of France (1214-1270), a just ruler who built the Sainte-Chapelle, cared for the poor and died on crusade in Tunis.", "Kings, the poor"),
    ("August 26", "Simeon Bachos, the Ethiopian Eunuch", A, "The treasurer of the queen of Ethiopia, baptised by Philip on the road to Gaza after reading Isaiah. Tradition says he carried the Gospel back to Africa.", "Africa, seekers, travellers"),
    ("August 27", "Thomas Gallaudet and Henry Winter Syle", A, "Two Episcopal priests (Gallaudet, d. 1902, and Syle, d. 1890) who ministered to the deaf community and founded churches for deaf congregations.", "The deaf, teachers of the deaf"),
    ("August 28", "Augustine of Hippo", PA, "Bishop of Hippo (354-430) who wrote 'Confessions' and 'The City of God'. His doctrine of grace deeply shaped Luther and Calvin and the Protestant Reformation.", "Theologians, those who seek God"),
    ("August 29", "The Beheading of John the Baptist", PA, "The forerunner who called Herod to repent was imprisoned and beheaded at the request of Herodias's daughter. His death is remembered as a witness to the truth.", "Truth-tellers"),
    ("August 30", "Margaret Ward, Margaret Clitherow and Anne Line", A, "Three English women martyred for sheltering priests during the persecution of Catholics under Elizabeth I.", "Women of courage, those who give shelter"),
    ("August 31", "John Bunyan", P, "English Baptist preacher and writer (1628-1688), imprisoned for preaching without a licence, who wrote 'The Pilgrim's Progress' in jail. He died on August 31.", "Writers, prisoners, pilgrims"),

    ("September 1", "Joshua the Prophet", P, "Moses' successor, who led Israel across the Jordan, and who proclaimed 'as for me and my house, we will serve the Lord'.", "Leaders, families who follow the Lord"),
    ("September 2", "N. F. S. Grundtvig", P, "Danish pastor, poet and educator (1783-1872) who wrote over a thousand hymns and founded the folk high school movement, putting faith and learning in the service of ordinary people.", "Hymn writers, educators, Denmark"),
    ("September 3", "Phoebe the Deacon", A, "The 'servant of the church at Cenchreae' whom Paul commended to the Romans, and who is thought to have carried his letter to Rome.", "Deacons, women in ministry"),
    ("September 4", "Moses the Lawgiver", P, "The prophet who led Israel out of Egypt and received the law on Sinai, who spoke to God face to face 'as a man speaks with his friend'.", "Leaders, those who seek freedom"),
    ("September 5", "Katharina Zell", A, "Reformer of Strasbourg (c. 1497-1562) who married a priest, defended clerical marriage in writing, cared for refugees and published hymns.", "Women reformers, refugees"),
    ("September 6", "Hannah More", A, "English writer and philanthropist (1745-1833) who founded schools for the poor in the Mendip Hills and wrote against the slave trade.", "Teachers, writers"),
    ("September 7", "Kassiani the Hymnographer", A, "Byzantine abbess and composer (c. 810-865) whose hymn for Holy Wednesday, sung to this day, tells of the woman who anointed Christ's feet.", "Hymn writers, women composers"),
    ("September 8", "The Nativity of the Blessed Virgin Mary", PA, "The birth of Mary is celebrated nine months after the Immaculate Conception in many traditions, and in the Anglican calendar it is a minor feast.", "Expectant mothers"),
    ("September 9", "Peter Claver", P, "Spanish Jesuit (1580-1654) who ministered to enslaved Africans arriving at Cartagena and called himself 'the slave of the slaves forever'.", "Those who serve the enslaved"),
    ("September 10", "Alexander Crummell", A, "African American Episcopal priest (1819-1898), scholar and missionary in Liberia, who founded the American Negro Academy and argued for the dignity of the Black church.", "Scholars, Liberia"),
    ("September 12", "John Henry Hobart", A, "Episcopal bishop of New York (1775-1830), a leader in the revival of the Church after the American Revolution.", "Bishops"),
    ("September 13", "John Chrysostom", P, "Archbishop of Constantinople (c. 347-407) whose preaching earned him the name 'golden-mouthed'. He urged care for the poor and was exiled by the court.", "Preachers"),
    ("September 14", "Holy Cross Day", "all", "The Church lifts up the cross as the sign of salvation and recalls the finding of the True Cross in Jerusalem. 'We adore you, O Christ, and we bless you, because by your holy cross you have redeemed the world'.", "Those who suffer, the faithful"),
    ("September 15", "Catherine of Genoa", A, "Italian mystic and nurse (1447-1510) who worked in a hospital in Genoa and wrote about purgatory and the love of God.", "Nurses, mystics"),
    ("September 16", "Cyprian of Carthage", P, "Bishop of Carthage (c. 200-258) who held the Church together through plague and persecution, writing 'On the Unity of the Church' and dying a martyr.", "Bishops, church unity"),
    ("September 17", "Hildegard of Bingen", PA, "German abbess (1098-1179), composer, writer, healer and visionary who wrote 'Scivias', sacred music and works on natural medicine.", "Composers, those who love creation"),
    ("September 18", "Dag Hammarskjold", P, "Swedish diplomat (1905-1961), Secretary-General of the United Nations, whose private journal 'Markings' shows a deep Christian faith. He died in a plane crash on a peace mission.", "Peacemakers, diplomats"),
    ("September 19", "Theodore of Tarsus", A, "Greek monk (c. 602-690) appointed archbishop of Canterbury at the age of 66, who organised the English Church and founded schools.", "Archbishops, teachers"),
    ("September 20", "John Coleridge Patteson and Companions", A, "Anglican bishop of Melanesia (1827-1871) killed on the island of Nukapu, together with others, after founding a school for islanders.", "Pacific Islanders, martyrs"),
    ("September 21", "Matthew, Apostle and Evangelist", PA, "The tax collector called from his booth by Jesus, who wrote the Gospel that begins the New Testament.", "Evangelists, those who change their lives"),
    ("September 22", "Jonah the Prophet", P, "The prophet who ran from God's call to Nineveh, was swallowed by a great fish and then preached repentance to a city that turned to the Lord.", "Those who run from God's call"),
    ("September 23", "Thecla of Iconium", A, "Early Christian woman converted by Saint Paul's preaching, venerated as the first woman martyr (c. 70) in the 'Acts of Paul and Thecla'.", "Women disciples"),
    ("September 24", "Anna Alexander", A, "African American Episcopal deaconess (1865-1947) who founded and led a church and school for Black children in Georgia.", "Teachers, deaconesses"),
    ("September 25", "The Peace of Augsburg", P, "Concluded on September 25, 1555, it gave Lutheran princes the right to practise their faith in the Holy Roman Empire, ending decades of conflict.", "Peacemakers, Lutheran churches"),
    ("September 26", "Lancelot Andrewes", A, "Anglican bishop (1555-1626) and a translator of the King James Bible, whose 'Private Prayers' are widely loved.", "Scholars, those who pray"),
    ("September 27", "Euphrosyne of Alexandria", A, "A young woman of the fifth century who disguised herself as a monk named Smaragdus and spent thirty-eight years in a monastery.", "Seekers of solitude"),
    ("September 28", "Paula and Eustochium", A, "Roman mother (347-404) and daughter who followed Jerome to Bethlehem, founded monasteries and helped with his Bible translation.", "Translators, nuns"),
    ("September 29", "Michael and All Angels", "all", "The Church honours the archangel Michael and all the angels who serve God and guard his people. 'Bless the Lord, O you his angels, you mighty ones who do his word'.", "Angels, guardians"),
    ("September 30", "Jerome", PA, "Latin scholar (c. 347-420) who translated the Bible into Latin, the Vulgate, and wrote commentaries. Lutherans and Anglicans honour him as a translator of Scripture.", "Translators, scholars, librarians"),

    ("October 1", "Remigius of Rheims", A, "Bishop of Reims (c. 437-533) who baptised Clovis, king of the Franks, and thereby helped bring the Frankish people into the Church.", "Bishops, France"),
    ("October 3", "John R. Mott", A, "American Methodist layman (1865-1955) who helped found the World Student Christian Federation and led the ecumenical movement. He received the Nobel Peace Prize in 1946.", "Students, ecumenists"),
    ("October 4", "Francis of Assisi", PA, "Italian friar (c. 1181-1226) who embraced poverty, preached to the birds and received the stigmata. The Lutheran and Anglican calendars honour him as a renewer of the Church.", "Animals, the poor, creation"),
    ("October 6", "William Tyndale", PA, "English translator (c. 1494-1536) who translated the New Testament into English and was strangled and burned for it in Belgium. His words shaped the King James Bible.", "Translators, those who give people the Bible in their own language"),
    ("October 7", "Henry Melchior Muhlenberg", P, "German-born pastor (1711-1787), 'patriarch of the Lutheran Church in America', who organised congregations in Pennsylvania and across the colonies.", "Pastors, Lutherans in America"),
    ("October 9", "Abraham the Patriarch", P, "The father of all who believe, who left his homeland at God's call and trusted God's promise of descendants as numerous as the stars.", "Those who step out in faith"),
    ("October 10", "Vida Dutton Scudder", A, "American Episcopal educator and social reformer (1861-1954), professor at Wellesley, who helped found the Church League for Industrial Democracy.", "Teachers, social reformers"),
    ("October 11", "Philip the Evangelist", PA, "One of the seven deacons of the Jerusalem church, who preached in Samaria and baptised the Ethiopian official, and whose four daughters prophesied.", "Evangelists, deacons"),
    ("October 12", "Edith Cavell", A, "English nurse (1865-1915) who helped hundreds of Allied soldiers escape from German-occupied Belgium and was executed on October 12. Her last words: 'Patriotism is not enough'.", "Nurses, those who resist injustice"),
    ("October 14", "Samuel Schereschewsky", A, "Lithuanian-born Jewish convert (1831-1906) who became Episcopal bishop of Shanghai and translated the Bible into Chinese despite paralysis.", "Translators, China"),
    ("October 15", "Teresa of Avila", PA, "Spanish Carmelite reformer (1515-1582) and mystic who wrote 'The Interior Castle' and taught that prayer is 'a close sharing between friends'.", "Mystics, those who pray"),
    ("October 16", "Hugh Latimer, Nicholas Ridley and Thomas Cranmer", A, "Three Anglican bishops burned under Queen Mary I at Oxford: Latimer and Ridley on October 16, 1555, Cranmer in 1556. Latimer said 'we shall this day light such a candle'.", "Martyrs of the English Reformation"),
    ("October 17", "Ignatius of Antioch", PA, "Bishop of Antioch martyred in Rome around 115. On his way he wrote letters to the churches, urging unity and love.", "Bishops, church unity"),
    ("October 18", "Luke, Evangelist", "all", "The physician and companion of Paul who wrote the Gospel of Luke and the Acts of the Apostles, with its special care for the poor, women and the outcast.", "Physicians, artists"),
    ("October 19", "Henry Martyn", A, "Anglican priest and missionary (1781-1812) who translated the New Testament into Urdu and Persian and died at the age of 31 in Tokat, Turkey.", "Translators, missionaries"),
    ("October 20", "Cornelius the Centurion", A, "The Roman officer of Caesarea whose household was the first Gentile family baptised by Peter, a sign that the Gospel was for all peoples.", "Soldiers, Gentile believers"),
    ("October 23", "James of Jerusalem", PA, "Brother of the Lord and first bishop of Jerusalem, called 'the Just', who presided at the council of Jerusalem and wrote the letter of James.", "Bishops, church unity"),
    ("October 25", "Tabitha (Dorcas) of Joppa", PA, "The disciple 'full of good works and acts of charity' whom Peter raised from the dead at Joppa. The widows showed him the garments she had made.", "Seamstresses, those who serve the poor"),
    ("October 26", "Philipp Nicolai, Johann Heermann and Paul Gerhardt", P, "Three German Lutheran hymn writers of the seventeenth century: Nicolai ('Wake, Awake'), Heermann ('Ah, Holy Jesus') and Gerhardt ('O Sacred Head, Now Wounded').", "Hymn writers, choirs"),
    ("October 28", "Simon and Jude, Apostles", PA, "Two of the twelve apostles, Simon the Zealot and Jude Thaddaeus. Tradition says they preached together in Persia and were martyred.", "Apostles"),
    ("October 29", "James Hannington and Companions", A, "Anglican bishop of Eastern Equatorial Africa (1847-1885) killed with his companions in Uganda on the orders of King Mwanga.", "Uganda, martyrs"),
    ("October 30", "Maryam of Qidun", A, "A young woman of Syria who devoted herself to prayer in the fourth century and cared for her uncle Abraham of Qidun.", "Those who care for family"),
    ("October 31", "Reformation Day", P, "On October 31, 1517, Martin Luther posted his Ninety-Five Theses on the door of the Castle Church in Wittenberg, beginning the Protestant Reformation. 'The just shall live by faith'.", "The Reformation, all Protestant churches"),

    ("November 2", "All Souls", A, "The Episcopal Church remembers all the faithful departed, trusting them to the mercy of God. 'Rest eternal grant them, O Lord, and let light perpetual shine upon them'.", "The departed, the bereaved"),
    ("November 3", "Richard Hooker", A, "English Anglican priest and theologian (1554-1600), whose 'Laws of Ecclesiastical Polity' defended the Church of England and taught the balance of Scripture, tradition and reason.", "Theologians, teachers"),
    ("November 4", "Adeline Blanchard Tyler and Companions", A, "Missionaries remembered by the Episcopal Church for their work in Africa and the Philippines.", "Missionaries"),
    ("November 6", "William Temple", A, "Archbishop of Canterbury (1881-1944), a theologian and social reformer who laid foundations for the British welfare state and the World Council of Churches.", "Archbishops, social reformers"),
    ("November 7", "Willibrord, Missionaries to the Netherlands", PA, "Northumbrian bishop (658-739) who became the 'apostle of the Frisians'. The Lutheran calendar also remembers Heyer, Ziegenbalg and Nommensen, missionaries to India and Indonesia.", "Missionaries"),
    ("November 8", "Johann von Staupitz", P, "Luther's superior and confessor (c. 1460-1524), who taught him that true repentance begins with the love of God and helped lead him to the Scriptures.", "Confessors, mentors"),
    ("November 9", "Martin Chemnitz and the Mystics of England", PA, "Martin Chemnitz (1522-1586) was a Lutheran theologian who helped write the Formula of Concord. The Episcopal Church recalls Richard Rolle, Walter Hilton and Margery Kempe, English mystics.", "Theologians, mystics"),
    ("November 10", "Martin Luther's Birthday", P, "Martin Luther was born on November 10, 1483, in Eisleben. He died in the same town in 1546. The Church remembers his birth and his work as a teacher of Scripture and grace.", "Reformers, teachers of Scripture"),
    ("November 11", "Martin of Tours", PA, "Roman soldier turned bishop (c. 316-397) who famously shared his cloak with a beggar. Lutherans honour him, and Luther himself was baptised on his feast.", "Soldiers, the poor"),
    ("November 12", "Charles Simeon", A, "Anglican priest (1759-1836) who served Holy Trinity, Cambridge, for 54 years, trained many young clergy and supported missionary societies.", "Preachers, missionaries"),
    ("November 14", "Justinian and the Consecration of Samuel Seabury", PA, "The Lutheran calendar remembers Emperor Justinian (d. 565), who built Hagia Sophia and codified Roman law. The Episcopal Church marks the 1784 consecration of Samuel Seabury as first American bishop.", "Bishops, builders"),
    ("November 15", "Herman of Alaska", A, "Russian Orthodox monk (c. 1756-1837) who served the Aleut people on Spruce Island and protected them from abuse.", "Native Alaskans, monks"),
    ("November 16", "Margaret of Scotland", A, "Anglo-Saxon princess and Queen of Scotland (c. 1045-1093) who supported church reform and cared for orphans and the poor.", "Queens, mothers"),
    ("November 17", "Elisabeth of Hungary", P, "Hungarian princess (1207-1231) who cared for the poor and the sick, building hospitals and giving away her goods. The ELCA remembers her on November 17.", "The poor, nurses"),
    ("November 18", "Hilda of Whitby", A, "English abbess (614-680) who hosted the Synod of Whitby and encouraged the poet Caedmon, the first English Christian poet.", "Abbesses, poets"),
    ("November 19", "Elizabeth of Hungary", PA, "Princess and charity worker who gave bread to the poor and cared for lepers. Her feast is on November 17 or 19 in various calendars.", "The poor, widows"),
    ("November 20", "Edmund, King and Martyr", A, "King of East Anglia (c. 841-870) killed by Danish invaders after refusing to renounce Christ.", "Kings, East Anglia"),
    ("November 21", "Gertrude the Great and Mechthilde of Hackeborn", A, "German nuns and mystics of the monastery of Helfta, who wrote about the love of Christ and gave great importance to the Scriptures and the liturgy.", "Mystics, nuns"),
    ("November 22", "C. S. Lewis", PA, "Oxford and Cambridge scholar and apologist (1898-1963), author of 'Mere Christianity', 'The Screwtape Letters' and 'The Chronicles of Narnia'. He died on November 22.", "Writers, apologists, readers"),
    ("November 23", "Clement of Rome", PA, "Bishop of Rome around 92-101, who wrote a letter to Corinth urging peace and order. Lutherans and Episcopalians remember him on November 23.", "Church unity, bishops"),
    ("November 24", "John Knox, Justus Falckner and Jehu Jones", PA, "John Knox (c. 1514-1572) led the Scottish Reformation and died on November 24. Lutherans remember Justus Falckner, Jehu Jones and William Passavant, American pastors.", "Reformers, pastors"),
    ("November 25", "Isaac Watts", P, "English Congregational minister (1674-1748), the 'father of English hymnody', author of 'Joy to the World' and 'When I Survey the Wondrous Cross'.", "Hymn writers, choirs"),
    ("November 26", "Sojourner Truth", PA, "Sojourner Truth (c. 1797-1883), a freed slave and preacher, spoke for the equality of women and the end of slavery. She died on November 26.", "Abolitionists, women"),
    ("November 28", "Kamehameha IV and Queen Emma of Hawaii", A, "The Hawaiian king and queen (1834-1863; 1836-1885) who founded the Anglican Church in Hawaii and the Queen's Hospital.", "Hawaii, hospital founders"),
    ("November 29", "Noah the Patriarch", P, "The righteous man who built the ark at God's command and survived the flood with his family. God set the rainbow as a sign of his covenant.", "Those who obey God in the face of ridicule"),
    ("November 30", "Andrew, Apostle", "all", "The fisherman who followed Jesus first and brought his brother Peter to him. Andrew is honoured as patron of Scotland, Greece and Russia.", "Fishermen, missionaries"),

    ("December 1", "Charles de Foucauld", A, "French hermit (1858-1916) who lived among the Tuareg in the Sahara, a witness of quiet presence. He was killed on December 1.", "Hermits, those who live among strangers"),
    ("December 2", "Martyrs of El Salvador", P, "Four American women missionaries, Maura Clarke, Ita Ford, Dorothy Kazel and Jean Donovan, killed by soldiers in El Salvador on December 2, 1980.", "Missionaries, the poor"),
    ("December 3", "Francis Xavier", PA, "Spanish Jesuit missionary (1506-1552) who carried the Gospel to India, Southeast Asia and Japan. He died on Sancian Island off China on December 3.", "Missionaries, Asia"),
    ("December 4", "John of Damascus", PA, "Syrian monk and theologian (c. 675-749) who defended icons and wrote hymns still sung at Easter, including 'The Day of Resurrection'.", "Hymn writers, theologians"),
    ("December 5", "Clement of Alexandria", A, "Greek Christian teacher (c. 150-215) who headed the catechetical school of Alexandria and argued that philosophy prepares for Christ.", "Teachers, philosophers"),
    ("December 6", "Nicholas of Myra", PA, "Bishop of Myra in Asia Minor (d. c. 342) known for secret gifts to the poor. The figure of Santa Claus grew from his legend.", "Children, sailors, those who give in secret"),
    ("December 7", "Ambrose of Milan", PA, "Bishop of Milan (c. 339-397) who baptised Augustine, wrote hymns and stood against the emperor to defend the Church's freedom.", "Bishops, hymn writers"),
    ("December 8", "Nicholas Ferrar", A, "English Anglican deacon (1593-1637) who founded a household community at Little Gidding devoted to prayer and charity.", "Deacons, those who live in community"),
    ("December 11", "Frederick Howden Jr.", A, "Episcopal priest and chaplain (1900-1942) who ministered to servicemen in World War II and was killed during the invasion of North Africa.", "Military chaplains"),
    ("December 12", "Francis de Sales and Jane de Chantal", A, "Savoyard bishop (1567-1622) and widowed baroness (1572-1641) who founded the Visitation Sisters. Francis wrote 'Introduction to the Devout Life', a classic for lay Christians.", "Writers, directors of souls"),
    ("December 13", "Lucy of Syracuse", PA, "Sicilian virgin and martyr (d. 304) whose name means 'light'. In Sweden and Norway Lucy's Day, with its processions of candles, brightens the dark days of winter.", "Light, the blind"),
    ("December 14", "John of the Cross", PA, "Spanish Carmelite mystic (1542-1591), co-reformer of the Carmelites, who wrote 'The Dark Night of the Soul' and the 'Spiritual Canticle'.", "Mystics, poets"),
    ("December 15", "Nino of Georgia", A, "A slave woman of the fourth century (c. 296-332) who brought the Gospel to Georgia after healing the queen. She is honoured as the 'enlightener of Georgia'.", "Georgia, women evangelists"),
    ("December 17", "Daniel and the Three Young Men", P, "Daniel and his friends Shadrach, Meshach and Abednego, who stayed faithful in Babylon and trusted God in the lions' den and the fiery furnace.", "Those who remain faithful in exile"),
    ("December 18", "Charles Wesley's Birthday", P, "Charles Wesley was born on December 18, 1707, and wrote some six thousand hymns, including 'Hark! The Herald Angels Sing', 'Love Divine' and 'And Can It Be'.", "Hymn writers, choirs"),
    ("December 19", "Adam and Eve", P, "The first man and woman, created in God's image, whose fall and promise of redemption frame the Bible's story of salvation.", "Families, the first parents"),
    ("December 20", "Katharina von Bora Luther", PA, "Former nun (1499-1552) who married Martin Luther, ran the household and farm of the Black Cloister and became a model of Reformation marriage and hospitality.", "Wives, mothers, household managers"),
    ("December 21", "Thomas, Apostle", PA, "The apostle who touched the wounds of Christ and said 'my Lord and my God'. His feast is kept on December 21 by the Lutheran and Episcopal calendars.", "Those who doubt, India"),
    ("December 22", "D. L. Moody's Death", P, "Dwight L. Moody (1837-1899), shoe salesman turned evangelist, preached to millions in America and Britain and founded schools and the Moody Bible Institute. He died on December 22.", "Evangelists, Bible schools"),
    ("December 24", "Vigil of the Nativity", "all", "On Christmas Eve the Church keeps vigil, reading the prophecies and the Gospel of the birth of Jesus, and prepares to welcome the light of Christ.", "All who await the Saviour"),
    ("December 26", "Stephen, Deacon and Martyr", "all", "The first Christian martyr, a deacon who served the poor and was stoned in Jerusalem as he prayed 'Lord, do not hold this sin against them'.", "Deacons, martyrs"),
    ("December 27", "John, Apostle and Evangelist", "all", "The beloved disciple who rested at the Last Supper on the breast of the Lord. Tradition says he wrote the fourth Gospel, three letters and the Book of Revelation.", "Writers, theologians"),
    ("December 28", "The Holy Innocents", PA, "The children of Bethlehem killed by King Herod. The Church remembers them as martyrs whose sacrifice stands for every child who suffers violence.", "Children"),
    ("December 29", "David the King", P, "The shepherd boy who became king of Israel, the 'sweet psalmist' and ancestor of Jesus. The Lutheran calendar remembers him in the days after Christmas.", "Kings, musicians, psalmists"),
    ("December 31", "John Wycliffe", P, "English priest and scholar (c. 1328-1384), called the 'Morning Star of the Reformation', who supervised the first complete English translation of the Bible. He died on December 31.", "Translators, reformers"),
]
